// === Tab: mySketch.js ===
let angle = 0;
let radius = 50;
let counter=0
let timer=0
let focusOnBallNumer=0
let stop=false
let timer2=0
function setup()
{
	createCanvas(windowWidth, windowHeight, WEBGL);
	background(random(255),random(255),random(255));

	for(i=0;i<300;i++)
	{
			eval("balls"+i+"=createballs("+i+");")
	}
}

function draw()
{
	timer2++
	if(timer2%30==0) stop=!stop
	if(stop==false)
	{
		timer++
		if(timer%100==0) focusOnBallNumer=round(random(-.1,.1))
		counter+=.0001

		let x = 1000 / 2 + cos(angle) * focusOnBallNumer;
		let y = 1000 / 2 + sin(angle) * focusOnBallNumer;
		angle += 0.02;
		camera(-100+x,100+y,-800+y,balls0.x,balls0.y,balls0.z,0,1,0);

		for(i=0;i<300;i++)
		{
				 eval("updateballs(balls"+i+");")
		}
	}
}

function createballs(num)
{
  let balls={}
	balls.num=num
  balls.x = 0
  balls.y = 0
	balls.z = 0
	balls.xOffset  = 0
  balls.yOffset  = 0
	balls.zOffset  = 0
	balls.s=random(200)
return balls
}


function updateballs(balls)
{
	rotateX(counter+random(.1))
	rotateY(counter+random(.1))
	rotateZ(counter+random(.1))

	balls.x = noise(balls.xOffset) * 1000;
  balls.y = noise(balls.xOffset + 100) * 1000;
	balls.z = noise(balls.xOffset + 40) * 1000;

	balls.s = constrain(balls.s, 1, 100);
	balls.s=balls.s+random(-1,1)

	push()
  translate(balls.x, balls.y, balls.z)
	stroke(random(255),random(255),random(255))
	strokeWeight(random(15))
  sphere(balls.s)
	pop()

  balls.xOffset += random(.008);

}

